DashboardBody:
{
  "widgets": [
    {
      "type": "metric",
      "x": 0, "y": 0, "width": 24, "height": 6,
      "properties": {
        "title": "Overall Score (avg) by agent — last 24h",
        "region": "us-east-1",
        "view": "timeSeries",
        "stacked": false,
        "period": 300,
        "stat": "Average",
        "yAxis": {"left": {"min": 0, "max": 1}},
        "metrics": [
          [{"expression": "SEARCH('{OnlineAgentEvaluation,AgentName,AgentType,Region} MetricName=\"Score\"', 'Average', 300)", "id": "e1"}]
        ]
      }
    },
    {
      "type": "metric",
      "x": 0, "y": 6, "width": 8, "height": 6,
      "properties": {
        "title": "Correctness (avg) by agent",
        "region": "us-east-1",
        "view": "timeSeries",
        "period": 300,
        "stat": "Average",
        "yAxis": {"left": {"min": 0, "max": 1}},
        "metrics": [
          [{"expression": "SEARCH('{OnlineAgentEvaluation,AgentName,AgentType,Region} MetricName=\"Correctness\"', 'Average', 300)", "id": "c1"}]
        ]
      }
    },
    {
      "type": "metric",
      "x": 8, "y": 6, "width": 8, "height": 6,
      "properties": {
        "title": "Helpfulness (avg) by agent",
        "region": "us-east-1",
        "view": "timeSeries",
        "period": 300,
        "stat": "Average",
        "yAxis": {"left": {"min": 0, "max": 1}},
        "metrics": [
          [{"expression": "SEARCH('{OnlineAgentEvaluation,AgentName,AgentType,Region} MetricName=\"Helpfulness\"', 'Average', 300)", "id": "h1"}]
        ]
      }
    },
    {
      "type": "metric",
      "x": 16, "y": 6, "width": 8, "height": 6,
      "properties": {
        "title": "Safety (avg) by agent",
        "region": "us-east-1",
        "view": "timeSeries",
        "period": 300,
        "stat": "Average",
        "yAxis": {"left": {"min": 0, "max": 1}},
        "metrics": [
          [{"expression": "SEARCH('{OnlineAgentEvaluation,AgentName,AgentType,Region} MetricName=\"Safety\"', 'Average', 300)", "id": "s1"}]
        ]
      }
    },
    {
      "type": "metric",
      "x": 0, "y": 12, "width": 12, "height": 6,
      "properties": {
        "title": "Sample volume (count of judgements per period) by agent",
        "region": "us-east-1",
        "view": "timeSeries",
        "stacked": true,
        "period": 300,
        "stat": "SampleCount",
        "metrics": [
          [{"expression": "SEARCH('{OnlineAgentEvaluation,AgentName,AgentType,Region} MetricName=\"Score\"', 'SampleCount', 300)", "id": "v1"}]
        ]
      }
    },
    {
      "type": "metric",
      "x": 12, "y": 12, "width": 12, "height": 6,
      "properties": {
        "title": "P10 / P50 score by agent (drift early-warning)",
        "region": "us-east-1",
        "view": "timeSeries",
        "period": 600,
        "yAxis": {"left": {"min": 0, "max": 1}},
        "metrics": [
          [{"expression": "SEARCH('{OnlineAgentEvaluation,AgentName,AgentType,Region} MetricName=\"Score\"', 'p10', 600)", "id": "p10"}],
          [{"expression": "SEARCH('{OnlineAgentEvaluation,AgentName,AgentType,Region} MetricName=\"Score\"', 'p50', 600)", "id": "p50"}]
        ]
      }
    }
  ]
}
